import React from 'react';

const TableViewComponent = ({ results }) => {
  if (!results || !results.length) {
    return <div>No results found.</div>;
  }

  return (
    <table className="results-table table-auto w-full border-collapse border border-gray-300">
      <thead className="bg-gray-100 dark:bg-gray-700">
        <tr>
          <th className="border p-2 text-left">Title</th>
          <th className="border p-2 text-left">Categories</th>
          <th className="border p-2 text-left">Year</th>
        </tr>
      </thead>
      <tbody>
        {results.map((result, index) => (
          <tr key={index} className="border-t hover:bg-gray-50 dark:hover:bg-gray-800">
            {/* Title column with image thumbnail */}
            <td className="border p-2">
              <div className="flex items-center gap-3">
                {result.page_image_ext && (
                  <a
                    href={result.full_title}
                    className="w-12 h-12 flex-shrink-0 rounded bg-cover bg-center"
                    style={{ backgroundImage: `url(${result.page_image_ext})` }}
                    title={result.title}
                  />
                )}
                <a
                  href={result.full_title}
                  className="text-blue-600 hover:underline dark:text-blue-300 font-medium"
                >
                  {result.title}
                </a>
              </div>
            </td>

            {/* Categories column with tags */}
            <td className="border p-2">
              <div className="flex flex-wrap items-center gap-2">
                <i className="fal fa-tags text-gray-500 dark:text-gray-300"></i>
                {Array.isArray(result.category) && result.category.length > 0 ? (
                  result.category.map((cat, i) => (
                    <a
                      key={i}
                      href={`/${cat.link}`}
                      title={`Category: ${cat.name}`}
                      className="px-2 py-1 rounded bg-blue-100 text-blue-700 text-sm hover:underline dark:bg-blue-800 dark:text-blue-200"
                    >
                      {cat.name}
                    </a>
                  ))
                ) : (
                  <span className="text-gray-500">—</span>
                )}
              </div>
            </td>

            {/* Year column */}
            <td className="border p-2">
              {result.year || <span className="text-gray-500">—</span>}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
};

export default TableViewComponent;
